'use strict';

// MODULES //

var Symbol = require( '@stdlib/symbol/ctor' );
var ArrayBuffer = require( '@stdlib/array/buffer' );
var Float64Array = require( '@stdlib/array/float64' );
var isSafeInteger = require( '@stdlib/assert/is-safe-integer' ).isPrimitive;
var isFiniteNumber = require( '@stdlib/math/base/assert/is-finite' );
var min = require( '@stdlib/math/base/special/min' );
var max = require( '@stdlib/math/base/special/max' );
var abs = require( '@stdlib/math/base/special/abs' );


// VARIABLES //

var MAX = 9007199254740991;
var prototype = Object.getPrototypeOf( Float64Array.prototype );
var tag = Object.getOwnPropertyDescriptor( prototype, Symbol.toStringTag ).get;
var getLength = Object.getOwnPropertyDescriptor( prototype, 'length' ).get;
var buffer = Object.getOwnPropertyDescriptor( prototype, 'buffer' ).get;
var byteOffset = Object.getOwnPropertyDescriptor( prototype, 'byteOffset' ).get;
var byteLength = Object.getOwnPropertyDescriptor( ArrayBuffer.prototype, 'byteLength' ).get;
var values = prototype.values;


// FUNCTIONS //

/**
* Validates exact primitive metadata.
* @private
* @param {number} value - metadata
* @throws {RangeError} invalid metadata
* @returns {integer} validated metadata
*/
function integer( value ) {
	if ( !isSafeInteger( value ) ) {
		throw new RangeError( 'invalid argument. Metadata must be primitive safe integers.' );
	}
	return value;
}

/**
* Adds exact signed metadata before evaluating an oversized expression.
* @private
* @param {integer} x - first term
* @param {integer} y - second term
* @throws {RangeError} inexact sum
* @returns {integer} exact sum
*/
function sum( x, y ) {
	if ( ( y > 0 && x > MAX-y ) || ( y < 0 && x < -MAX-y ) ) {
		throw new RangeError( 'invalid argument. Inexact indexed sum.' );
	}
	return x+y;
}

/**
* Computes a checked product.
* @private
* @param {NonNegativeInteger} count - nonnegative count
* @param {integer} stride - signed stride
* @throws {RangeError} inexact product
* @returns {integer} exact product
*/
function product( count, stride ) {
	if ( count !== 0 && abs(stride) > MAX/count ) {
		throw new RangeError( 'invalid argument. Inexact indexed product.' );
	}
	return integer( count*stride );
}

/**
* Computes a greatest common divisor.
* @private
* @param {PositiveInteger} x - first value
* @param {PositiveInteger} y - second value
* @returns {PositiveInteger} divisor
*/
function gcd( x, y ) {
	var z;
	while ( y !== 0 ) {
		z = x%y;
		x = y;
		y = z;
	}
	return x;
}

/**
* Validates an intrinsic ordinary-backed full injective view.
* @private
* @param {Float64Array} x - input view
* @param {PositiveInteger} h - logical rows
* @param {PositiveInteger} n - logical columns
* @param {integer} r - row stride
* @param {integer} c - column stride
* @param {integer} o - offset
* @throws {TypeError} invalid brand or backing
* @throws {RangeError} invalid geometry
* @returns {Object} indexed byte envelope
*/
function view( x, h, n, r, c, o ) {
	var first;
	var data;
	var size;
	var last;
	var lo;
	var hi;
	var dr;
	var dc;
	var g;
	if ( tag.call(x) !== 'Float64Array' ) {
		throw new TypeError( 'invalid argument. Must provide an intrinsic Float64Array.' );
	}
	values.call( x ); // Intrinsic detached and current out-of-bounds validation.
	data = buffer.call( x );
	size = byteLength.call( data ); // Rejects shared backing and tag spoofs.
	integer( r );
	integer( c );
	integer( o );
	if ( o < 0 || (h > 1 && r === 0) || (n > 1 && c === 0) ) {
		throw new RangeError( 'invalid argument. Offsets must be nonnegative and active strides nonzero.' );
	}
	if ( h > 1 && n > 1 ) {
		g = gcd( abs(r), abs(c) );
		if ( abs(c)/g < h && abs(r)/g < n ) {
			throw new RangeError( 'invalid argument. The full indexed view must be injective.' );
		}
	}
	dr = product( h-1, r );
	dc = product( n-1, c );
	lo = sum( sum(o, min(dr, 0)), min(dc, 0) );
	hi = sum( sum(o, max(dr, 0)), max(dc, 0) );
	if ( lo < 0 || hi >= getLength.call(x) ) {
		throw new RangeError( 'invalid argument. Indexed view exceeds the current intrinsic extent.' );
	}
	first = sum( byteOffset.call(x), product(lo, 8) );
	last = sum( byteOffset.call(x), product(sum(hi, 1), 8) );
	if ( last > size ) {
		throw new RangeError( 'invalid argument. Indexed view exceeds current backing extent.' );
	}
	return {
		'buffer': data,
		'first': first,
		'last': last
	};
}

/**
* Rejects overlapping indexed envelopes before writes.
* @private
* @param {Array<Object>} views - active envelopes
* @throws {RangeError} overlapping envelopes
* @returns {void}
*/
function disjoint( views ) {
	var i;
	var j;
	for ( i = 0; i < views.length; i++ ) {
		for ( j = i+1; j < views.length; j++ ) {
			if ( views[i].buffer === views[j].buffer && views[i].first < views[j].last && views[j].first < views[i].last ) {
				throw new RangeError( 'invalid argument. Indexed byte envelopes overlap.' );
			}
		}
	}
}

/**
* Validates selected triangle and dimensions.
* @private
* @param {string|integer} uplo - selected triangle
* @param {NonNegativeInteger} N - matrix order
* @param {NonNegativeInteger} KD - bandwidth
* @throws {TypeError} invalid selector
* @throws {RangeError} invalid dimensions
* @returns {integer} numeric triangle
*/
function scalars( uplo, N, KD ) {
	if ( uplo === 'upper' || uplo === 121 ) {
		uplo = 121;
	} else if ( uplo === 'lower' || uplo === 122 ) {
		uplo = 122;
	} else {
		throw new TypeError( 'invalid argument. Invalid triangle.' );
	}
	integer( N );
	integer( KD );
	if ( N < 0 || N > 2147483646 || KD < 0 || KD > 2147483646 ) {
		throw new RangeError( 'invalid argument. Dimensions must be in [0,2147483646].' );
	}
	return uplo;
}


// MAIN //

/**
* Validates all active views, aliases and selected finite diagonals.
* @private
* @param {integer} uplo - numeric triangle
* @param {NonNegativeInteger} N - order
* @param {NonNegativeInteger} KD - bandwidth
* @param {Float64Array} AB - band view
* @param {integer} r - row stride
* @param {integer} c - column stride
* @param {integer} o - band offset
* @param {Float64Array} S - vector output
* @param {integer} ss - vector stride
* @param {integer} os - vector offset
* @param {Float64Array} SCOND - scalar output
* @param {integer} oc - scalar offset
* @param {Float64Array} AMAX - scalar output
* @param {integer} om - scalar offset
* @throws {TypeError} invalid storage
* @throws {RangeError} invalid views or nonfinite selected diagonals
* @returns {void}
*/
function validate( uplo, N, KD, AB, r, c, o, S, ss, os, SCOND, oc, AMAX, om ) { // eslint-disable-line max-params -- Preserve the adopted fourteen-argument ndarray contract.
	var scalarC;
	var scalarM;
	var matrix;
	var vector;
	var ai;
	var j;
	scalarC = view( SCOND, 1, 1, 0, 0, oc );
	scalarM = view( AMAX, 1, 1, 0, 0, om );
	disjoint( [ scalarC, scalarM ] );
	if ( N === 0 ) {
		return;
	}
	matrix = view( AB, KD+1, N, r, c, o );
	vector = view( S, N, 1, ss, 0, os );
	disjoint( [ matrix, vector, scalarC, scalarM ] );
	ai = o + ((uplo === 121) ? KD*r : 0);
	for ( j = 0; j < N; j++ ) {
		if ( !isFiniteNumber(AB[ai+(j*c)]) ) {
			throw new RangeError( 'invalid argument. Selected diagonals must be finite.' );
		}
	}
}


// EXPORTS //

validate.scalars = scalars;
validate.integer = integer;
validate.sum = sum;
validate.product = product;
validate.view = view;
validate.disjoint = disjoint;
module.exports = validate;
